# name: doublet_run_choice
# description: Among trials whose sequences differ in their number of runs of length exactly 2 (HH or TT bounded by the other face), the proportion choosing the sequence with MORE doublets; observed above null_mean means people treat short pairs as a hallmark of randomness more than the model predicts, below means they penalise them.
def test_statistic(df):
    a = df["sequence_a"]; b = df["sequence_b"]
    def dbl(s):
        u = pd.unique(s)
        def f(x):
            runs, cur = [], 1
            for i in range(1, len(x)):
                if x[i] == x[i - 1]:
                    cur += 1
                else:
                    runs.append(cur); cur = 1
            runs.append(cur)
            return sum(1 for r in runs if r == 2)
        return s.map({x: f(x) for x in u}).to_numpy()
    da, db = dbl(a), dbl(b)
    mask = da != db
    if not mask.any():
        return 0.5
    c = df["chose_left"].to_numpy()
    chose_more = np.where(da > db, c, 1 - c)
    return float(chose_more[mask].mean())

# name: late_switch_concentration_choice
# description: Among trials whose sequences differ in (switches in the second half minus switches in the first half), the proportion choosing the sequence whose switching is concentrated LATER (streaky start, alternating end); observed above null_mean means people judge sequences by how they end/begin in a way the order-blind switch-rate term misses (below: they prefer early alternation).
def test_statistic(df):
    a = df["sequence_a"]; b = df["sequence_b"]
    def late(s):
        u = pd.unique(s)
        def f(x):
            t = [int(x[i] != x[i + 1]) for i in range(len(x) - 1)]
            h = len(t) // 2
            return sum(t[len(t) - h:]) - sum(t[:h])
        return s.map({x: f(x) for x in u}).to_numpy()
    la, lb = late(a), late(b)
    mask = la != lb
    if not mask.any():
        return 0.5
    c = df["chose_left"].to_numpy()
    chose_late = np.where(la > lb, c, 1 - c)
    return float(chose_late[mask].mean())

# name: short_sequence_switchier_choice
# description: Among trials of length <= 5 whose sequences differ in switch count, the proportion choosing the sequence with MORE switches; observed above null_mean means on short sequences people favour alternation more than the model (whose ideal switching rate is shared across lengths) predicts, below means less.
def test_statistic(df):
    a = df["sequence_a"]; b = df["sequence_b"]
    L = a.str.len()
    def sw(s):
        u = pd.unique(s)
        m = {x: sum(1 for i in range(len(x) - 1) if x[i] != x[i + 1]) for x in u}
        return s.map(m).to_numpy()
    sa, sb = sw(a), sw(b)
    mask = (L.to_numpy() <= 5) & (sa != sb)
    if not mask.any():
        return 0.5
    c = df["chose_left"].to_numpy()
    chose_more = np.where(sa > sb, c, 1 - c)
    return float(chose_more[mask].mean())

# name: distinct_triplet_choice
# description: Among length >= 7 trials whose sequences differ in the number of DISTINCT length-3 substrings (local pattern variety), the proportion choosing the sequence with more distinct triplets; observed above null_mean means people reward local pattern complexity beyond what the model's switch/run/symmetry features capture, below means less.
def test_statistic(df):
    a = df["sequence_a"]; b = df["sequence_b"]
    def tri(s):
        u = pd.unique(s)
        return s.map({x: len({x[i:i + 3] for i in range(len(x) - 2)}) for x in u}).to_numpy()
    ta, tb = tri(a), tri(b)
    mask = (a.str.len().to_numpy() >= 7) & (ta != tb)
    if not mask.any():
        return 0.5
    c = df["chose_left"].to_numpy()
    chose_more = np.where(ta > tb, c, 1 - c)
    return float(chose_more[mask].mean())

# name: complement_symmetric_choice
# description: Among trials where exactly one sequence (length >= 4) equals its own reverse with H/T swapped and is NOT strictly alternating, the proportion choosing that antisymmetric sequence; observed below null_mean means people reject non-alternating antisymmetric sequences even more than the model's single shared antisymmetry weight predicts (above: the weight over-penalises them, e.g. it is driven by strict alternation).
def test_statistic(df):
    def anti(s):
        u = pd.unique(s)
        def f(x):
            if len(x) < 4:
                return 0
            alt = all(x[i] != x[i + 1] for i in range(len(x) - 1))
            fl = "".join("T" if ch == "H" else "H" for ch in x[::-1])
            return int(x == fl and not alt)
        return s.map({x: f(x) for x in u}).to_numpy()
    aa, ab = anti(df["sequence_a"]), anti(df["sequence_b"])
    mask = aa != ab
    if not mask.any():
        return 0.5
    c = df["chose_left"].to_numpy()
    chose_anti = np.where(aa == 1, c, 1 - c)
    return float(chose_anti[mask].mean())
